function viewState(){if((tool==='cutout'||tool==='effects'&&s.target==='custom'&&fxBrush!=='none')&&(s.punch.enabled||s.mockup.enabled||s.composition!=='overlay'||s.blank))return{...s,blank:false,photoVisible:true,ratio:'original',composition:'overlay',punch:{...s.punch,enabled:false},mockup:{...s.mockup,enabled:false},pattern:{...s.pattern,enabled:false},block:{...s.block,enabled:false},frame:{...s.frame,type:'none'},word:{...s.word,enabled:false},calendar:{...s.calendar,enabled:false},wire:{...s.wire,enabled:false},layers:[],strokes:[],nodes:[]};return s;}
