function read(path){return path.split('.').reduce((a,k)=>a?.[k],s)}
function set(path,v){const keys=path.split('.'),key=keys.pop();keys.reduce((a,k)=>a[k],s)[key]=v}
function section(title,body,detail=''){return `<section class="section">${title?`<div class="section-label">${title}<span class="detail">${detail}</span></div>`:''}${body}</section>`}
function range(label,path,min,max,unit='',step=1){const value=read(path)??min;return `<div class="slider-row"><label for="r-${path}">${label}<output data-output="${path}">${value}${unit}</output></label><input id="r-${path}" type="range" data-path="${path}" min="${min}" max="${max}" step="${step}" value="${value}" data-unit="${unit}"></div>`}
function color(label,path){return `<label class="color-row">${label}<input type="color" data-path="${path}" value="${esc(read(path))}"></label>`}
function check(label,path){return `<label class="toggle-row">${label}<input type="checkbox" data-path="${path}" ${read(path)?'checked':''}></label>`}
function select(label,path,options){return `<label class="field-label">${label}<select data-path="${path}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(read(path))===String(v)?'selected':''}>${t}</option>`).join('')}</select></label>`}
function btn(label,action,cls='small-btn wide'){return `<button class="${cls}" data-action="${action}">${label}</button>`}
function numberField(label,path){return `<label class="field-label">${label}<input type="number" data-path="${path}" value="${Math.round(read(path)*100)/100}" step="any"></label>`}
