if(tool==='punch'){const shape=[...controls.querySelectorAll(':scope > .section')].find(n=>n.querySelector('.shape-grid'))?.outerHTML||'';const custom=[...controls.querySelectorAll(':scope > .section')].find(n=>n.querySelector('[data-path="pattern.custom"]'))?.outerHTML||'';const all=[...controls.querySelectorAll(':scope > .section')],auto=all.filter(n=>n.querySelector('.section-label')?.textContent.startsWith('펀칭 이미지')||n.querySelector('.section-label')?.textContent.startsWith('어디에, 어떻게')).map(n=>n.outerHTML).join('');const setup=document.createElement('div');setup.innerHTML=manualPunchControls();if(s.punch.mode==='auto'){setup.querySelector('[data-path="punch.enabled"]')?.closest('label')?.remove();controls.innerHTML=setup.children[0].outerHTML+auto+shape+custom;}else controls.innerHTML=setup.innerHTML+shape+custom;}

