function renderLayers(){const data=[...s.layers].reverse().map(l=>`<div class="layer-item ${selected===l.id?'selected':''}"><span class="layer-symbol">${l.kind==='image'?`<img src="${esc(assetURLs.get(l.asset)||'')}" alt="">`:'T'}</span><button class="layer-name" data-select="${l.id}">${esc(l.kind==='text'?l.text.replace(/\n/g,' ').slice(0,18):({background:'종이 배경',paper:'오린 종이 · 영수증',subject:'메인 피사체',extra:'추가 피사체'}[l.collageRole]||'사진 스티커'))}<small>${l.behind?'피사체 뒤쪽':l.kind==='text'?'텍스트':'이미지'}</small></button><button class="layer-eye" data-visible="${l.id}" aria-label="레이어 ${l.visible===false?'보이기':'숨기기'}">${l.visible===false?'○':'◉'}</button></div>`).join('');$('#layers').innerHTML=data+`<div class="layer-item"><span class="layer-symbol">◐</span><button class="layer-name" data-tool="effects">효과 레이어<small>${s.effectLayers.length}개 중첩 · 선택해서 순서·강도 조절</small></button></div>`+s.effectLayers.slice().reverse().map(l=>`<div class="layer-item ${s.effectSelection===l.id?'selected':''}"><span class="layer-symbol">◈</span><button class="layer-name" data-fx-select="${l.id}">${esc(effects.find(e=>e[0]===l.fx.type)?.[1]||'효과')}<small>${effectRegions.find(e=>e[0]===l.region)?.[1]} · ${l.fx.strength}%</small></button><button class="layer-eye" data-fx-visible="${l.id}">${l.visible===false?'○':'◉'}</button></div>`).join('')+`<div class="layer-item"><span class="layer-symbol">✳</span><button class="layer-name" data-tool="shapes">기호 패턴<small>${s.pattern.enabled?s.pattern.count+'개의 작은 기호':'아직 적용하지 않음'}</small></button><button class="layer-eye" data-action="pattern-toggle" aria-label="기호 표시 전환">${s.pattern.enabled?'◉':'○'}</button></div><div class="layer-item"><span class="layer-symbol">◌</span><button class="layer-name" data-tool="cutout">피사체<small>${s.mask?'분리된 선택 영역':'누끼를 만들어주세요'}</small></button></div><div class="layer-item"><span class="layer-symbol">${s.photo?`<img src="${esc(assetURLs.get(s.photo)||'')}" alt="">`:'＋'}</span><button class="layer-name" data-tool="layout">원본 사진<small>배경 레이어</small></button><button class="layer-eye" data-action="photo-toggle" aria-label="사진 표시 전환">${s.photoVisible?'◉':'○'}</button></div>`;}
function renderPalette(){$('#palette').innerHTML=s.palette.map(c=>`<button class="swatch" style="background:${c}" data-palette="${c}" aria-label="색상 ${c} 적용"></button>`).join('')}
function switchTool(next){symbolStamp=false;cursorPoint=null;selectedPunch=null;if(drag)finishDrag();touches.clear();const previous=tool;tool=next;if(previous!==next)$('.control-panel').scrollTop=0;brushMode='none';fxBrush='none';nodesMode=false;faceManual=false;if(previous!==next){s.showMask=false;s.showCustomMask=false;}if(previous==='cutout'&&next!=='cutout')refreshCollageSubject(api).catch(e=>toast(e.message));interaction.style.cursor='grab';document.querySelectorAll('.tool[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));refresh()}
async function loadImage(url,key=uid()){const img=new Image();img.src=url;await img.decode();assets.set(key,img);assetURLs.set(key,url);return key}
async function fileImage(file){if(!file.type.startsWith('image/'))throw Error('이미지 파일을 선택해주세요.');if(file.size>30*1024*1024)throw Error('30MB 이하의 이미지를 선택해주세요.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(!img.width||!img.height)throw Error('이미지를 읽을 수 없습니다.');const scale=Math.min(1,3000/Math.max(img.width,img.height)),c=canvasOf(img.width*scale,img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);return await loadImage(c.toDataURL('image/png'))}finally{URL.revokeObjectURL(url)}}
async function setPhoto(file){try{const id=await fileImage(file);photoGeneration++;mutate(()=>{s.photo=id;s.mask=null;s.effectLayers.forEach(l=>l.mask=null);s.customMask=null;s.showCustomMask=false;s.faces=[];s.faceBlur.enabled=false;s.subjectOnly=false;s.showMask=false;s.subjectFront=false;s.panX=s.panY=s.rotation=0;s.zoom=100;s.blank=false;s.photoVisible=true;s.target='all';});extractPalette();renderPresets();toast('새 사진을 불러왔어요.')}catch(e){toast(e.message)}}
function extractPalette(){if(!assets.get(s.photo))return;const c=canvasOf(80,80),x=c.getContext('2d');x.drawImage(assets.get(s.photo),0,0,80,80);const p=x.getImageData(0,0,80,80).data,bins=new Map();for(let i=0;i<p.length;i+=4){const colors=[p[i],p[i+1],p[i+2]].map(v=>Math.round(v/40)*40),key=colors.map(v=>Math.min(255,v).toString(16).padStart(2,'0')).join('');bins.set(key,(bins.get(key)||0)+1)}s.palette=[...bins].sort((a,b)=>b[1]-a[1]).slice(0,5).map(([v])=>'#'+v);renderPalette();}
const presets=[['original','오리지널'],['paper','페이퍼 도트'],['cyber','사이버 팝'],['mint','민트 비즈'],['mono','모노 타입'],['film','필름 무드']];
function applyPreset(state,key){clearDecorations(state);state.effects.custom=baseEffect();state.effectLayers=[];state.effectSelection=null;state.target='all';state.showCustomMask=false;state.mockup.enabled=false;state.composition='overlay';state.effects.all=baseEffect();state.effects.background=baseEffect();state.effects.subject=baseEffect();state.brightness=state.contrast=state.saturation=100;state.warmth=state.blur=0;state.pattern.enabled=false;state.block.enabled=false;state.frame.type='none';state.subjectOnly=false;state.showMask=false;state.word.enabled=false;state.blank=false;if(key==='paper'){Object.assign(state.effects.all,{type:'halftone',size:7,strength:85,colored:false,paper:'#f7f2db',color:'#233c2b'});}if(key==='cyber'){Object.assign(state.effects.all,{type:'ring',size:7,strength:36,paper:'#f5ffed',color:'#417664'});Object.assign(state.pattern,{enabled:true,region:state.mask?'background':'all',shape:'mix',size:22,count:150,layout:'edge',cutout:false});state.saturation=145;}if(key==='mint'){Object.assign(state.effects.all,{type:'beads',size:9,strength:85,paper:'#d9f1d1'});}if(key==='mono'){Object.assign(state.effects.all,{type:'ascii',size:10,strength:100,colored:false,color:'#162818',paper:'#e3ebd8'});}if(key==='film'){Object.assign(state.effects.all,{type:'grain',size:8,strength:55});state.saturation=68;state.warmth=25;state.frame.type='polaroid';}}
async function renderPresets(){await document.fonts.ready;$('#presets').replaceChildren();for(const [key,label]of presets){const p=structuredClone(s);applyPreset(p,key);const c=canvasOf(100,100);render(p,assets,c);const b=document.createElement('button');b.className='preset';b.dataset.preset=key;b.innerHTML=`<img class="preset-preview" src="${c.toDataURL()}" alt=""><span>${label}</span>`;$('#presets').append(b)}}
function addText(text='test',shape=false){const id=uid();mutate(()=>{s.layers.push({...typeDefaults,id,kind:'text',text,x:.5,y:.5,size:shape?90:55,font:'Pretendard',textStyle:'plain',thickness:7,strokeColor:'#ffffff',color:shape?s.pattern.color:'#ffffff',bold:true,shadow:false,outline:false,rotation:0,opacity:100,visible:true,behind:false});selected=id});switchTool('text')}
async function addStickers(files){try{const ids=await Promise.all([...files].slice(0,12).map(fileImage));mutate(()=>ids.forEach((id,i)=>{const l={id:uid(),kind:'image',asset:id,x:.4+i%3*.08,y:.4+i%3*.08,size:380,rotation:0,opacity:100,visible:true,behind:false,shadow:false,paperBorder:0,paperRoughness:0,borderColor:'#ffffff',brightness:100,saturation:100,blur:0,mask:'none'};s.layers.push(l);selected=l.id;}));switchTool('layout');toast(`${ids.length}장의 사진을 추가했어요.`)}catch(e){toast(e.message)}}
function reorderLayer(dir){mutate(()=>{const i=s.layers.findIndex(l=>l.id===selected),to=clamp(i+dir,0,s.layers.length-1);if(i>=0)[s.layers[i],s.layers[to]]=[s.layers[to],s.layers[i]]})}
function undo(){if(!undoStack.length)return;redoStack.push(snapshot());s=JSON.parse(undoStack.pop());photoGeneration++;selected=null;pendingEdit=null;refresh();renderPresets()}
